registerDiagram({
  id: 'go-fencing-token',
  roadmap: 'go', module: 14, topic: 'Distributed building blocks in Go',
  kind: 'sequence',
  title: 'Why distributed locks need fencing tokens',
  desc: 'A lease-based lock can expire while its holder is paused, so two workers both believe they hold it. A monotonically increasing token checked by the storage makes the stale write harmless.',
  actors: [
    { id: 'a', label: 'worker A', icon: '🐹', color: 'blue' },
    { id: 'l', label: 'lock service', sub: 'etcd lease / Redis', icon: '🔒', color: 'purple', info: 'etcd: concurrency.NewMutex on a session lease; the key\'s creation revision is a ready-made fencing token. Redis: SET key token NX PX ttl, released with a Lua compare-and-delete so you never delete someone else\'s lock.' },
    { id: 'b', label: 'worker B', icon: '🐹', color: 'green' },
    { id: 's', label: 'storage', sub: 'checks the token', icon: '🗄️', color: 'teal', info: 'The protected resource must take part: it remembers the highest token it has seen and rejects writes carrying an older one, for example with a conditional update such as UPDATE … WHERE fence < $token.' },
  ],
  steps: [
    { section: 'Lease-based lock' },
    { from: 'a', to: 'l', label: 'acquire (lease 10s)', caption: 'Worker A asks for the lock. Locks are leases with a TTL, so a crashed holder cannot block everyone forever.' },
    { from: 'l', to: 'a', label: 'granted, token 33', reply: true, caption: 'A gets the lock plus a fencing token, a number that only ever increases. In etcd, the revision at which the lock key was created.' },
    { from: 'a', to: 'a', label: 'long pause (GC)', caption: 'A stalls for 15 s: a long GC pause, a VM migration, or a network partition. From A\'s point of view no time has passed.' },
    { from: 'l', to: 'l', label: 'lease expires', caption: 'A did not renew in time, so the lease expires and the lock is free.' },
    { from: 'b', to: 'l', label: 'acquire (lease 10s)', caption: 'Worker B asks for the lock.' },
    { from: 'l', to: 'b', label: 'granted, token 34', reply: true, caption: 'B legitimately acquires the lock with a higher token.' },
    { section: 'Two holders at once' },
    { from: 'b', to: 's', label: 'write x, token 34', caption: 'B writes and sends its token along with the write.' },
    { from: 's', to: 's', label: 'highest token = 34', caption: 'Storage records the highest token it has accepted.' },
    { from: 'a', to: 's', label: 'write x, token 33', caption: 'A wakes up still believing it holds the lock and writes. Checking "do I still hold it?" first would not help: the pause can happen between the check and the write.' },
    { from: 's', to: 'a', label: 'rejected: 33 < 34', reply: true, caption: 'The stale write is rejected. Safety comes from the resource checking the token, not from the lock service alone.' },
    { section: 'Release' },
    { from: 'b', to: 'l', label: 'release if still mine', caption: 'Release must be conditional, deleting the key only if it still holds B\'s token or lease (a Redis Lua compare-and-delete, or revoking the etcd lease). The same fencing caveat applies to leader election.' },
  ],
});

